import sys, os, json, csv, io, re, unicodedata


def nid(s):
    return str(s).strip().upper()


def ntext(s):
    s = unicodedata.normalize("NFC", str(s)).casefold()
    s = "".join(c if c.isalnum() else " " for c in s)
    return " ".join(s.split())


def read_batch(path):
    with open(path, encoding="utf-8", newline="") as f:
        text = f.read()
    text = text.replace("\r\n", "\n")
    meta = {}
    recs = []
    if path.endswith(".jsonl"):
        first = True
        for line in text.split("\n"):
            if not line.strip():
                continue
            o = json.loads(line)
            if first:
                meta = o
                first = False
                continue
            marks = {}
            for m in o.get("marks", []):
                r = int(m["rank"])
                if "write_in" in m and m["write_in"] is not None:
                    marks.setdefault(r, []).append(("w", m["write_in"]))
                else:
                    marks.setdefault(r, []).append(("c", m["candidate"]))
            recs.append((o["contest"], marks))
    else:
        lines = text.split("\n")
        i = 0
        while i < len(lines) and (lines[i].startswith("#") or not lines[i].strip()):
            l = lines[i]
            if l.startswith("#"):
                m = re.match(r"#\s*([^:]*?)\s*:\s*(.*?)\s*$", l)
                if m:
                    meta[m.group(1).strip().lower()] = m.group(2)
            i += 1
        rows = list(csv.reader(io.StringIO("\n".join(lines[i:]))))
        rows = [r for r in rows if r and any(c.strip() for c in r)]
        if rows:
            hdr = [h.strip() for h in rows[0]]
            rcols = {}
            for k, h in enumerate(hdr):
                m = re.fullmatch(r"rank(\d+)", h)
                if m:
                    rcols[k] = int(m.group(1))
            bi = hdr.index("contest")
            for r in rows[1:]:
                marks = {}
                for k, rk in rcols.items():
                    if k < len(r) and r[k] != "":
                        for part in r[k].split("|"):
                            if part.startswith("WI:"):
                                marks.setdefault(rk, []).append(("w", part[3:]))
                            elif part.strip():
                                marks.setdefault(rk, []).append(("c", part))
                recs.append((r[bi], marks))
    return meta, recs


def main():
    inp, out = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    cvr = os.path.join(inp, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        meta, recs = read_batch(p)
        b = str(meta["batch"])
        rev = int(str(meta["revision"]).strip())
        if b not in best or rev > best[b][0]:
            best[b] = (rev, str(meta.get("status", "final")).strip().lower(), recs)
    bycontest = {}
    for rev, status, recs in best.values():
        if status == "void":
            continue
        for c, marks in recs:
            bycontest.setdefault(c, []).append(marks)

    result = {"election": el["election"], "contests": []}
    for c in el["contests"]:
        result["contests"].append(count(c, bycontest.get(c["id"], [])))
    with open(out, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


def prepare(contest, marks, wmap, withdrawn):
    """Return list of rankings: ('skip',) ('pass',) ('choice',c) ('over',)"""
    mr = contest["max_ranks"]
    seen = set()
    out = []
    for r in range(1, mr + 1):
        ms = set()
        for kind, v in marks.get(r, []):
            if kind == "w":
                t = ntext(v)
                if t in wmap:
                    ms.add(wmap[t])
            else:
                ms.add(nid(v))
        if not ms:
            out.append(("skip",))
            continue
        ms -= withdrawn
        if not ms:
            out.append(("pass",))
            continue
        before = set(seen)
        seen |= ms
        ms -= before
        if not ms:
            out.append(("skip",))
        elif len(ms) == 1:
            out.append(("choice", next(iter(ms))))
        else:
            out.append(("over",))
    return out


def count(contest, ballots):
    names = {}
    withdrawn = set()
    cands = []
    for cd in contest["candidates"]:
        names[nid(cd["id"])] = cd["id"]
        if cd.get("status") == "withdrawn":
            withdrawn.add(nid(cd["id"]))
        else:
            cands.append(nid(cd["id"]))
    wmap = {}
    for w in contest.get("write_ins", []):
        names[nid(w["id"])] = w["id"]
        cands.append(nid(w["id"]))
        for t in [w["name"]] + list(w.get("aliases", [])):
            wmap[ntext(t)] = nid(w["id"])
    lot = {nid(x): i for i, x in enumerate(contest.get("lot_order", []))}
    prepared = [prepare(contest, m, wmap, withdrawn) for m in ballots]
    n = len(prepared)

    def read(rk, cont):
        L = len(rk)
        for i, e in enumerate(rk):
            t = e[0]
            if t == "choice":
                if e[1] in cont:
                    return e[1]
            elif t == "over":
                return None
            elif t == "skip":
                if i + 1 >= L or rk[i + 1][0] == "skip":
                    return None
        return None

    continuing = set(cands)
    rounds = []
    history = []
    winner = None
    while True:
        tal = {c: 0 for c in continuing}
        for rk in prepared:
            c = read(rk, continuing)
            if c is not None:
                tal[c] += 1
        active = sum(tal.values())
        history.append(tal)
        rd = {"round": len(history), "tallies": {names[c]: v for c, v in tal.items()},
              "exhausted": n - active, "eliminated": []}
        rounds.append(rd)
        if active == 0:
            break
        win = [c for c, v in tal.items() if v * 2 > active]
        if win or len(continuing) == 1:
            winner = win[0] if win else next(iter(continuing))
            break
        zeros = [c for c, v in tal.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tal.values())
            tied = [c for c, v in tal.items() if v == m]
            k = len(history) - 2
            while len(tied) > 1 and k >= 0:
                mm = min(history[k][c] for c in tied)
                tied = [c for c in tied if history[k][c] == mm]
                k -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: lot.get(c, -1))]
            elim = tied
        rd["eliminated"] = sorted(names[c] for c in elim)
        continuing -= set(elim)
    return {"contest": contest["id"], "ballots": n,
            "winner": names[winner] if winner else None, "rounds": rounds}


main()
